// -----------------------------
// Parse the raw data from nodes
// -----------------------------
function safeJsonParse(str, label) {
  try {
    return JSON.parse(str);
  } catch (e) {
    throw new Error(`Failed to JSON.parse for ${label}: ${e?.message || e}`);
  }
}

function getNodeData(nodeName) {
  const raw = $(nodeName).all()?.[0]?.json?.data;
  if (!raw) throw new Error(`Missing node data: ${nodeName}`);
  return raw;
}

const employeeNode = getNodeData('Get Employee');
const historyNode = getNodeData('Get Employment History');
const emergencyNode = getNodeData('GET Emergency Contacts');

const employeeRaw = safeJsonParse(employeeNode, 'Get Employee')?.data;
const historyRaw = safeJsonParse(historyNode, 'Get Employment History')?.data?.items;
const emergencyItems = safeJsonParse(emergencyNode, 'GET Emergency Contacts')?.data?.items;

if (!employeeRaw) throw new Error('Employee payload missing .data');
if (!Array.isArray(historyRaw)) throw new Error('Employment History payload missing .data.items array');
if (!Array.isArray(emergencyItems)) throw new Error('Emergency Contacts payload missing .data.items array');

const emergencyContact = emergencyItems[0] || null;

// -----------------------------
// Determine latest employment
// -----------------------------
function safeDateValue(v) {
  const d = new Date(v);
  return Number.isFinite(d.getTime()) ? d.getTime() : 0;
}

let latestEmployment = {};
if (historyRaw.length > 0) {
  latestEmployment = historyRaw
    .slice()
    .sort((a, b) => safeDateValue(b?.start_date) - safeDateValue(a?.start_date))[0] || {};
}

// -----------------------------
// Mapping functions
// -----------------------------
const paygroupTypeMapping = {
  'Full-time': 'full_time',
  'Part-time': 'part_time',
  'Casual': 'casual',
};

function mapPaygroup(type) {
  const t = String(type || '').trim();
  const mapped = paygroupTypeMapping[t];
  if (!mapped) throw new Error(`Unable to map paygroup: ${type}`);
  return mapped;
}

const employmentTypeMapping = {
  'Full-time': 10,
  'Part-time': 11,
  'Casual': 12,
  'External Provider': 13,
  Volunteer: 14,
};

function mapEmploymentType(type) {
  const t = String(type || '').trim();
  const mapped = employmentTypeMapping[t];
  if (!mapped) throw new Error(`Unable to map employmentType: ${type}`);
  return mapped;
}

function mapGender(gender) {
  if (!gender) return 1;
  const normalized = String(gender).trim().toLowerCase();
  const mapping = {
    female: 0,
    male: 1,
    'non-binary': 2,
    'prefer not to say': 3,
  };
  const mapped = mapping[normalized];
  if (mapped === undefined) throw new Error(`Unable to map gender: ${gender}`);
  return mapped;
}

// IMPORTANT: explicitly map titles. Do NOT default unknowns to admin.
const jobTitleMapping = {
  'Personal Care Worker': 'personal_care_worker',
  'Enrolled Nurse': 'enrolled_nurse',
  'Registered Nurse': 'registered_nurse',
  'Domestic Assistant': 'domestic_assistant',
  'Clinical Nurse Specialist': 'clinical_nurse_specialist',
  'Neighbourhood Leader': 'neighbourhood_leader',
  'Care Concierge': 'care_concierge',
};

function mapJobTitle(title) {
  const key = String(title || '').trim();
  return jobTitleMapping[key] || 'admin';
}

