// Cost centre mapping (your provided list)
// -----------------------------
const costCentreToTeamCustomId = {
  Admin: 'admin',
  'Brisbane - DA': 'brisbane_da',
  'Brisbane East': 'brisbane_east',
  'Brisbane North': 'brisbane_north',
  'Brisbane North - DA': 'brisbane_north_da',
  'Brisbane South': 'brisbane_south',
  'Brisbane South - DA': 'brisbane_south_da',
  Cairns: 'cairns',
  'Cairns - DA': 'cairns_da',
  Canberra: 'canberra',
  'Canberra - DA': 'canberra_da',
  'Central Coast': 'central_coast',
  'Central Coast - DA': 'central_coast_da',
  Darwin: 'darwin',
  'Darwin - DA': 'darwin_da',
  'Gold Coast': 'goldcoast',
  'Gold Coast - DA': 'goldcoast_da',
  Ipswich: 'ipswich',
  'Ipswich - DA': 'ipswich_da',
  'Northern NSW': 'northern_nsw',
  'Northern NSW - DA': 'northern_nsw_da',
  'Sunshine Coast': 'sunshine_coast',
