  Toowoomba: 'toowoomba',
  'Toowoomba - DA': 'toowoomba_da',
  Townsville: 'townsville',
  'Townsville - DA': 'townsville_da',
};

function mapTeamCustomId(primaryCostCentreName) {
  if (!primaryCostCentreName) return null;
  const key = String(primaryCostCentreName).split(' / ').pop().trim();
  const mapped = costCentreToTeamCustomId[key] ?? null;
  if (!mapped) {
    throw new Error(`Unable to map primary_cost_centre.name to teamcustomid: ${primaryCostCentreName}`);
  }
  return mapped;
}

// -----------------------------
