function hasDomesticAssistanceEntitlement(teams) {
  if (!Array.isArray(teams)) return false;
  return teams.some((t) => {
    const name = String(t?.name || '').trim();
    return / - DA$/i.test(name) ?? name.trim().toLowerCase() === 'domestic assistance';
  });
}

function getSupabaseCandidateTeamIds(teams) {
  if (!Array.isArray(teams) || teams.length === 0) return [];
  return teams
    .map((t) => String(t?.id || '').trim())
    .filter(Boolean)
    .filter((id) => SUPABASE_TEAM_ALLOW_IDS.has(id));
}

function mapSupabaseTeams(teams) {
  if (!Array.isArray(teams) || teams.length === 0) {
    throw new Error('Unable to map supabaseteams: employee has no teams');
  }

  if (hasDomesticAssistanceEntitlement(teams)) {
    return [DOMESTIC_ASSISTANCE_TEAM_ID];
  }

  const ids = getSupabaseCandidateTeamIds(teams);

  if (!ids.length) {
    throw new Error('Unable to map supabaseteams: no allowed team IDs found');
  }

  return [...new Set(ids)];
}

function mapSupabasePrimaryTeam(teams) {
  if (!Array.isArray(teams) || teams.length === 0) {
    throw new Error('Unable to map supabaseprimaryteam: employee has no teams');
  }

  if (hasDomesticAssistanceEntitlement(teams)) {
    return DOMESTIC_ASSISTANCE_TEAM_ID;
  }

  const primary = getSupabaseCandidateTeamIds(teams)[0] || null;

  if (!primary) {
    throw new Error('Unable to map supabaseprimaryteam: no allowed primary team ID found');
  }

  return primary;
}

