function formatPhoneNumber(number) {
  if (!number) return '';
  const digits = String(number).replace(/\D/g, '');

  // Already AU mobile in E.164 form
  if (/^614\d{8}$/.test(digits)) return digits;

  // Local AU mobile
  if (/^04\d{8}$/.test(digits)) return '614' + digits.slice(2);

  // Mixed form: 61 + 04
  if (/^6104\d{8}$/.test(digits)) return '614' + digits.slice(4);

  // Guaranteed mobiles: anchor on trailing 4xxxxxxxx
  const m = digits.match(/(4\d{8})$/);
  if (m) return '61' + m[1];

  throw new Error(`Unexpected mobile format: ${number}`);
}

function formatAUPhoneFlexible(number) {
  if (!number) return '';
  const digits = String(number).replace(/\D/g, '');

  // --- Mobiles ---
  if (/^614\d{8}$/.test(digits)) return digits;
  if (/^04\d{8}$/.test(digits)) return '614' + digits.slice(2);
  if (/^6104\d{8}$/.test(digits)) return '614' + digits.slice(4);

  // --- Landlines ---
  // +61 7 xxxx xxxx
  if (/^61[2378]\d{8}$/.test(digits)) return digits;

  // 07 / 02 / 03 / 08 local
  if (/^[2378]\d{8}$/.test(digits)) return '61' + digits;

  throw new Error(`Unexpected AU phone format: ${number}`);
}

function parseAddress(addr) {
  const out = { address: '', suburb: '', state: '', postcode: '' };
  if (!addr) return out;

  let parts = String(addr)
    .split(',')
    .map((p) => p.trim())
    .filter(Boolean);

  if (parts.length === 0) return out;

  // 1) Drop trailing country tokens like "AU" or "Australia"
  const last = parts.at(-1)?.toUpperCase();
  if (last === 'AU' || last === 'AUS' || last === 'AUSTRALIA') {
    parts = parts.slice(0, -1);
  }

  // Helper matchers
  const isPostcode = (s) => /^\d{4}$/.test(String(s || '').trim());
  const AU_STATES = new Set(['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT']);
  const isState = (s) => AU_STATES.has(String(s || '').trim().toUpperCase());

  // 2) Find postcode index by scanning from the end
  let postcodeIdx = -1;
  for (let i = parts.length - 1; i >= 0; i--) {
    if (isPostcode(parts[i])) {
      postcodeIdx = i;
      break;
    }
  }

  // If we can't find a postcode, fall back to old behavior (best effort)
  if (postcodeIdx === -1) {
    out.address = parts[0] ?? '';
    out.suburb = parts[1] ?? '';
    out.state = parts[2] ?? '';
    out.postcode = (parts[3] ?? '').replace(/\D/g, '').slice(-4);
    return out;
  }

  out.postcode = parts[postcodeIdx];

  // 3) State is usually right before postcode, but validate
  let stateIdx = postcodeIdx - 1;
  if (stateIdx >= 0 && !isState(parts[stateIdx])) {
    // Try find a state token somewhere before postcode
    for (let i = postcodeIdx - 1; i >= 0; i--) {
      if (isState(parts[i])) {
        stateIdx = i;
        break;
      }
    }
  }

  if (stateIdx >= 0 && isState(parts[stateIdx])) {
    out.state = String(parts[stateIdx]).toUpperCase();
  } else {
    // If still not found, best effort: keep the token before postcode as state
    out.state = parts[postcodeIdx - 1] || '';
    stateIdx = postcodeIdx - 1;
  }

  // 4) Suburb is token immediately before state (if it exists)
  const suburbIdx = stateIdx - 1;
  out.suburb = suburbIdx >= 0 ? parts[suburbIdx] : '';

  // 5) Address is everything before suburb
  const addressParts = suburbIdx > 0 ? parts.slice(0, suburbIdx) : parts.slice(0, 1);

  // Optional: dedupe exact repeated segments (your case has duplicated street)
  out.address = [...new Set(addressParts)].join(', ');

  return out;
}

