const msg = $json.error?.message || '';

let appCode = null;
let authUserId = null;

if (msg.includes('auth_exists_without_public_or_archived')) {
  appCode = 404;   // auth-only case

  try {
    // msg: '400 - "<json-string>"'
    const parts = msg.split(' - ');
    if (parts.length >= 2) {
      const outer = parts.slice(1).join(' - ');  // "\"{\\\"code\\\":...}\""

      // First parse: remove the outer quotes -> inner JSON string
      const innerJsonString = JSON.parse(outer); // '{"code":"P0001",...}'

      // Second parse: get the actual object
      const pgError = JSON.parse(innerJsonString); // { code, details, message, ... }

      // details is itself a JSON string
      const details = JSON.parse(pgError.details); // { code: 404, user_id, custom_id }

      authUserId = details.user_id ?? null;
    }
  } catch (e) {
    authUserId = null;
  }

} else if (msg.includes('missing_everywhere_cannot_auto_create')) {
  appCode = 400;   // missing everywhere
}

return {
  json: {
    ...$json,
    appCode,    // 404 or 400
    authUserId, // uuid or null
  },
};

